// Disjoint Force-Directed Graph — Network, route: ref
// Source: disjoint-force-directed-graph_2
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useRef } from 'react';
import * as d3 from 'd3';

// ---- inlined from disjointForceGraph ----
// Seven genuinely disconnected components: a star, a ring, a tree, a clique, a chain,
// a pair and a lone node. The id prefix letter is the component, and so the color group.
const edges: Array<[string, string]> = [
  ['A0', 'A1'], ['A0', 'A2'], ['A0', 'A3'], ['A0', 'A4'],
  ['A0', 'A5'], ['A0', 'A6'], ['A0', 'A7'], ['A0', 'A8'],

  ['B0', 'B1'], ['B1', 'B2'], ['B2', 'B3'], ['B3', 'B4'],
  ['B4', 'B5'], ['B5', 'B6'], ['B6', 'B0'],

  ['C0', 'C1'], ['C0', 'C2'], ['C1', 'C3'], ['C1', 'C4'], ['C2', 'C5'], ['C2', 'C6'],

  ['D0', 'D1'], ['D0', 'D2'], ['D0', 'D3'], ['D0', 'D4'], ['D1', 'D2'],
  ['D1', 'D3'], ['D1', 'D4'], ['D2', 'D3'], ['D2', 'D4'], ['D3', 'D4'],

  ['E0', 'E1'], ['E1', 'E2'], ['E2', 'E3'], ['E3', 'E4'], ['E4', 'E5'],

  ['F0', 'F1'],
];

// G0 has no edges at all: the case a centering force would leave stranded off-canvas.
const isolated = ['G0'];

interface GraphNode {
  id: string;
  group: number;
}

interface GraphLink {
  source: string;
  target: string;
  value: number;
}

const ids = [...new Set(edges.flat()), ...isolated];

const disjointGraph: { nodes: GraphNode[]; links: GraphLink[] } = {
  nodes: ids.map((id) => ({ id, group: id.charCodeAt(0) - 65 })),
  links: edges.map(([source, target], i) => ({ source, target, value: 1 + (i % 3) })),
};

/** Nodes keyed by id, and links naming their endpoints by that id. Components may be disjoint. */
export type Data = {
  nodes: { id: string; group: number }[];
  links: { source: string; target: string; value: number }[];
};

const SEED = 42;
const SETTLE_TICKS = 400;

interface SimNode extends d3.SimulationNodeDatum {
  id: string;
  group: number;
  degree: number;
}

interface SimLink extends d3.SimulationLinkDatum<SimNode> {
  value: number;
}

// forceLink replaces the endpoint ids with node objects once the simulation initializes.
const at = (end: SimLink['source'], axis: 'x' | 'y') => (end as SimNode)[axis] ?? 0;

export default function DisjointForceDirectedGraph({
  data = disjointGraph,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.5);
  const svgRef = useRef<SVGSVGElement>(null);

  const seeded = useMemo(() => {
    const random = d3.randomLcg(SEED);
    const degree = new Map(data.nodes.map((n) => [n.id, 0]));
    for (const link of data.links) {
      degree.set(link.source, (degree.get(link.source) ?? 0) + 1);
      degree.set(link.target, (degree.get(link.target) ?? 0) + 1);
    }
    return data.nodes.map((n) => ({
      ...n,
      degree: degree.get(n.id) ?? 0,
      x: (random() - 0.5) * width * 0.6,
      y: (random() - 0.5) * height * 0.6,
    }));
  }, [data, width, height]);

  const radius = useMemo(() => d3.scaleSqrt().domain([0, 8]).range([4, 11]), []);

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    svg.selectAll('*').remove();

    // Fresh copies every run so a StrictMode remount settles from identical inputs.
    const nodes: SimNode[] = seeded.map((n) => ({ ...n }));
    const links: SimLink[] = data.links.map((l) => ({ ...l }));

    // forceX/forceY instead of forceCenter: positioning forces pull every component toward
    // the origin individually, so detached subgraphs cannot drift out of the viewport.
    const simulation = d3
      .forceSimulation<SimNode, SimLink>(nodes)
      .randomSource(d3.randomLcg(SEED))
      .force(
        'link',
        d3
          .forceLink<SimNode, SimLink>(links)
          .id((d) => d.id)
          .distance(36)
      )
      .force('charge', d3.forceManyBody<SimNode>().strength(-170))
      .force('collide', d3.forceCollide<SimNode>().radius((d) => radius(d.degree) + 4))
      .force('x', d3.forceX<SimNode>().strength(0.05))
      .force('y', d3.forceY<SimNode>().strength(0.1))
      .stop();
    simulation.tick(SETTLE_TICKS);

    const link = svg
      .append('g')
      .attr('stroke', 'var(--muted)')
      .attr('stroke-opacity', 0.55)
      .selectAll('line')
      .data(links)
      .join('line')
      .attr('stroke-width', (d) => Math.sqrt(d.value))
      .attr('x1', (d) => at(d.source, 'x'))
      .attr('y1', (d) => at(d.source, 'y'))
      .attr('x2', (d) => at(d.target, 'x'))
      .attr('y2', (d) => at(d.target, 'y'));

    const node = svg
      .append('g')
      .attr('stroke', 'var(--bg)')
      .attr('stroke-width', 1.5)
      .selectAll<SVGCircleElement, SimNode>('circle')
      .data(nodes)
      .join('circle')
      .attr('r', (d) => radius(d.degree))
      .attr('fill', (d) => d3.schemeObservable10[d.group % 10])
      .attr('cx', (d) => d.x ?? 0)
      .attr('cy', (d) => d.y ?? 0);

    node.append('title').text((d) => d.id);

    simulation.on('tick', () => {
      link
        .attr('x1', (d) => at(d.source, 'x'))
        .attr('y1', (d) => at(d.source, 'y'))
        .attr('x2', (d) => at(d.target, 'x'))
        .attr('y2', (d) => at(d.target, 'y'));
      node.attr('cx', (d) => d.x ?? 0).attr('cy', (d) => d.y ?? 0);
    });

    node.call(
      d3
        .drag<SVGCircleElement, SimNode>()
        .on('start', (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart();
          d.fx = d.x;
          d.fy = d.y;
        })
        .on('drag', (event, d) => {
          d.fx = event.x;
          d.fy = event.y;
        })
        .on('end', (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null;
          d.fy = null;
        })
    );

    return () => {
      simulation.on('tick', null).stop();
      svg.selectAll('*').remove();
    };
  }, [data, seeded, radius, width, height]);

  if (width === 0) return null;

  return (
    <svg
      ref={svgRef}
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Disjoint force-directed graph of seven disconnected components, nodes draggable"
    />
  );
}
